const setRepairTicketCommentVisibility = `-- name: SetRepairTicketCommentVisibility :execrows
WITH changed AS (
 UPDATE repair_ticket_comment c SET internal=$3,account_id=NULL
 FROM repair_ticket r
 WHERE c.org_id=$1 AND c.id=$4 AND c.ticket_id=$2
 AND r.org_id=c.org_id AND r.id=c.ticket_id AND r.deleted_at IS NULL
 AND ($3::boolean OR r.shared_with_clients)
 AND c.deleted_at IS NULL AND c.account_id IS NULL
 RETURNING c.ticket_id
)
UPDATE repair_ticket r SET updated_at=clock_timestamp()
WHERE r.org_id=$1 AND r.id=$2
AND EXISTS(SELECT 1 FROM changed WHERE changed.ticket_id=r.id)
`

type SetRepairTicketCommentVisibilityParams struct {
	OrgID     int64
	TicketID  int64
	Internal  bool
	CommentID int64
}

func (q *Queries) SetRepairTicketCommentVisibility(ctx context.Context, arg SetRepairTicketCommentVisibilityParams) (int64, error) {
	result, err := q.exec(ctx, q.setRepairTicketCommentVisibilityStmt, setRepairTicketCommentVisibility,
		arg.OrgID,
		arg.TicketID,
		arg.Internal,
		arg.CommentID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

